<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useBrandingStore} from '@/stores/branding'
import {useToast} from '@/composables/useToast'
import {DEFAULT_LOGIN_COPY,LOGIN_COPY_FIELDS,type LoginCopyKey} from '@/types/loginCopy'
import LoginPresentation from '@/components/LoginPresentation.vue'
const branding=useBrandingStore(),toast=useToast(),busy=ref(false),ready=ref(false)
const draft=ref({...branding.settings,login_copy:{...branding.settings.login_copy}})
const previewState=ref('normal')
const previewError=computed(()=>previewState.value==='normal'||previewState.value==='submitting'?'':draft.value.login_copy[previewState.value as LoginCopyKey])
onMounted(async()=>{await branding.load();draft.value={...branding.settings,login_copy:{...branding.settings.login_copy}};ready.value=true})
async function save(){busy.value=true;try{await branding.save(draft.value);toast.show('登录页面配置已保存')}catch(e){toast.show(e instanceof Error?e.message:'保存失败')}finally{busy.value=false}}
function reset(){draft.value.login_copy={...DEFAULT_LOGIN_COPY};toast.show('已填入默认文案，保存后生效')}
const groups=[{title:'品牌与标题',keys:['badge','eyebrow','title']},{title:'表单与按钮',keys:['username_label','username_placeholder','password_label','password_placeholder','submit','submitting','show_password','hide_password']},{title:'帮助与页脚',keys:['help','footer']},{title:'校验与异常提示',keys:['username_required','password_required','invalid_credentials','rate_limited','service_unavailable','generic_error']}]
</script>
<template><div v-if="ready" class="row g-4"><div class="col-xl-7"><form @submit.prevent="save"><div class="card mb-3"><div class="card-header"><h3 class="card-title">登录页内容</h3></div><div class="card-body"><p class="text-secondary">所有文字按纯文本展示。可选文案留空即可隐藏；平台名称与说明同时用于全站品牌设置。</p><label class="form-label" for="login-site-name">平台名称 / 浏览器标题</label><input id="login-site-name" v-model="draft.site_name" class="form-control mb-3" required maxlength="80"/><label class="form-label" for="login-tagline">品牌副标题</label><textarea id="login-tagline" v-model="draft.tagline" class="form-control mb-3" maxlength="500"/><label class="form-label" for="login-description">品牌介绍</label><textarea id="login-description" v-model="draft.login_description" class="form-control" maxlength="500"/></div></div><div v-for="g in groups" :key="g.title" class="card mb-3"><div class="card-header"><h3 class="card-title">{{g.title}}</h3></div><div class="card-body"><div v-for="field in LOGIN_COPY_FIELDS.filter(f=>g.keys.includes(f.key))" :key="field.key" class="mb-3"><label :for="'copy-'+field.key" class="form-label" :class="{required:field.required}">{{field.label}}</label><textarea :id="'copy-'+field.key" v-model="draft.login_copy[field.key]" class="form-control" :required="field.required" maxlength="500" rows="2"/></div></div></div><div class="d-flex gap-2 pb-4"><button type="submit" class="btn btn-primary" :disabled="busy">{{busy?'正在保存…':'保存登录页配置'}}</button><button type="button" class="btn" :disabled="busy" @click="reset">填入默认文案</button><a href="/login" target="_blank" rel="noopener" class="btn">打开登录页</a></div></form></div><div class="col-xl-5"><div class="preview-wrap"><h3>实时预览</h3><label class="form-label" for="login-preview-state">预览状态</label><select id="login-preview-state" v-model="previewState" class="form-select mb-3"><option value="normal">正常</option><option value="submitting">登录中</option><option v-for="f in LOGIN_COPY_FIELDS.filter(f=>groups[3].keys.includes(f.key))" :key="f.key" :value="f.key">{{f.label}}</option></select><LoginPresentation :settings="draft" preview :busy="previewState==='submitting'" :error="previewError"/></div></div></div><p v-else class="text-secondary">正在读取登录页设置…</p></template>
<style scoped>.preview-wrap{position:sticky;top:24px;max-height:calc(100vh - 48px);overflow:auto;padding-right:4px}</style>
